import { tags } from "typia";

/**
 * Risk case statistics segment for the admin risk overview.
 *
 * Provides aggregated counts and breakdowns of risk cases, such as open vs.
 * closed and severity levels, based on shopping_mall_risk_cases and
 * shopping_mall_risk_case_events.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallRiskCaseStatsSummary = {
  /** Total number of currently open risk cases across the platform. */
  openCaseCount: number & tags.Type<"int32">;

  /**
   * Number of risk cases closed within the primary reporting window (for
   * example, the last 24 hours).
   */
  recentlyClosedCaseCount: number & tags.Type<"int32">;

  /**
   * Number of currently open risk cases that are classified as high severity
   * according to risk case configuration.
   */
  highSeverityOpenCaseCount: number & tags.Type<"int32">;

  /** Number of currently open risk cases classified as medium severity. */
  mediumSeverityOpenCaseCount: number & tags.Type<"int32">;

  /** Number of currently open risk cases classified as low severity. */
  lowSeverityOpenCaseCount: number & tags.Type<"int32">;
};
